const listActiveDrivers = `-- name: ListActiveDrivers :many

SELECT id, name, active, position, status, last_returned_at, created_at, pos_number, pushover_device FROM drivers WHERE active ORDER BY position ASC, created_at ASC
`

// Drivers -------------------------------------------------------------------
func (q *Queries) ListActiveDrivers(ctx context.Context) ([]Driver, error) {
	rows, err := q.db.QueryContext(ctx, listActiveDrivers)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	var items []Driver
	for rows.Next() {
		var i Driver
		if err := rows.Scan(
			&i.ID,
			&i.Name,
			&i.Active,
			&i.Position,
			&i.Status,
			&i.LastReturnedAt,
			&i.CreatedAt,
			&i.PosNumber,
			&i.PushoverDevice,
		); err != nil {
			return nil, err
		}
		items = append(items, i)
	}
	if err := rows.Close(); err != nil {
		return nil, err
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

